  3 = 'Part rent, part mortgage (shared equity)',
  4 = 'Rent it',
  5 = 'Live rent-free, incl. relatives/friends',
  7 = 'Other arrangement'
)

# Apply labels to variables
for (age in c(14, 15, 16, 17, 18, 19, 20, 25, 32)) {
  var_name <- paste0('hown', age)
