map_missing_values <- function(x) {
  if (is.na(x)) return(-3)
  if (x == -999 || x == -998 || x == -997 || x == -995) return(-2)
  if (x == -99) return(-3)
  if (x == -94) return(-8)
  if (x == -92) return(-9)
  if (x == -91) return(-1)
  if (x == -1) return(-1)
  return(x)
}

# Function to harmonize tenure categories
harmonize_tenure <- function(x, wave) {
  if (is.na(x)) return(NA)

  # Define mappings for each wave
  if (wave == 32) {
    return(x)
  } else if (wave %in% c(14, 15, 16, 17, 19, 20)) {
    if (x == 1) return(1)  # Owned outright
    if (x == 2) return(2)  # Being bought on a mortgage/loan
    if (x == 3) return(3)  # Shared ownership
    if (x %in% c(4, 5, 6)) return(4)  # Rent it (Rented from Council, Housing Association, or privately)
    if (x == 7) return(5)  # Rent free
    if (x == 8) return(7)  # Other
  } else if (wave == 25) {
    if (x == 1) return(1)  # Own outright
    if (x == 2) return(2)  # Own, buying with help of mortgage/loan
    if (x == 3) return(3)  # Part rent, part mortgage (shared equity)
    if (x %in% c(4, 5)) return(4)  # Rent it (Rent inc Housing Benefit/Local Housing Allowance or Rent-free)
    if (x == 6) return(7)  # Squatting or other arrangement
  }

  return(x)
}

# Function to create detailed tenure variables
create_detailed_tenure <- function(data, age, prefix) {
