    mutate(!!var_name := harmonize_tenure(!!sym(var_name), age)) %>%
    mutate(!!var_name := ifelse(is.na(!!sym(var_name)), -3, !!sym(var_name)))

  return(data)
}

# Function to create collapsed tenure variables
